<script lang="ts">
 import {onMount} from 'svelte';import {locale,t} from '$lib/i18n';
 let fields=$state<any[]>([]),message=$state(''),failed=$state(false),busy=$state(false),recipient=$state('');
 async function load(){const r=await fetch('/api/v1/settings');if(r.ok)fields=(await r.json()).fields.filter((f:any)=>f.key.startsWith('notifications.smtp_config.')||['auth.admin_emails','auth.email_password_resets','auth.administrator_mail_enabled','misc.frontend_url'].includes(f.key)).map((f:any)=>({...f,value:f.kind==='list'?(f.value??[]).join(', '):f.kind==='secret'?'':f.value}));}
 async function save(e:SubmitEvent){e.preventDefault();busy=true;failed=false;try{const values=Object.fromEntries(fields.filter(f=>!f.environment).map(f=>[f.key,f.kind==='list'?f.value.split(',').map((s:string)=>s.trim()).filter(Boolean):f.kind==='number'?Number(f.value):f.value]));const r=await fetch('/api/v1/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({values})});const d=await r.json();if(!r.ok)throw Error(d.detail);message='Email settings saved and applied.';await load();}catch(e){failed=true;message=(e as Error).message;}finally{busy=false;}}
 async function test(send:boolean){busy=true;failed=false;try{const r=await fetch('/api/v1/settings/mail-test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recipient:send?recipient:null})});const d=await r.json();if(!r.ok)throw Error(d.detail);message=send?'Test email sent. Check the recipient inbox.':'SMTP connection successful.';}catch(e){failed=true;message=(e as Error).message;}finally{busy=false;}}
 onMount(load);
</script>
<section class="space-y-5 rounded-2xl border bg-card p-5"><h2 class="text-xl font-bold">{t($locale,'Email & accounts')}</h2><p class="text-sm text-muted-foreground">{t($locale,'Configure outgoing SMTP for email confirmation, password recovery and administrator notifications. IMAP is not required. Save before testing. Existing accounts are preserved.')}</p><form onsubmit={save} class="grid gap-4 md:grid-cols-2">{#each fields as field}<label class="min-w-0 text-sm">{t($locale,field.label)}{#if field.kind==='bool'}<input type="checkbox" bind:checked={field.value} disabled={busy||field.environment} class="ml-3"/>{:else}<input type={field.kind==='secret'?'password':field.kind==='number'?'number':'text'} autocomplete={field.kind==='secret'?'new-password':'off'} bind:value={field.value} disabled={busy||field.environment} placeholder={field.configured?t($locale,'Saved — leave empty to keep'):''} class="mt-1 block w-full min-w-0 rounded-lg border bg-background p-2"/>{/if}</label>{/each}<button disabled={busy} class="rounded-lg bg-primary px-4 py-2 text-primary-foreground">{t($locale,'Save email settings')}</button></form><div class="flex flex-wrap items-end gap-3"><button disabled={busy} onclick={()=>test(false)} class="rounded-lg border px-4 py-2">{t($locale,'Test connection')}</button><label class="min-w-0 flex-1 text-sm">{t($locale,'Test recipient')}<input type="email" bind:value={recipient} class="mt-1 w-full rounded-lg border bg-background p-2"/></label><button disabled={busy||!recipient} onclick={()=>test(true)} class="rounded-lg border px-4 py-2">{t($locale,'Send test email')}</button></div>{#if message}<p role="status" class:text-destructive={failed}>{t($locale,message)}</p>{/if}</section>
